<template>
  <DebugPanel
    ref="debugPanelRef"
    v-bind="$attrs"
    :debug-manager="debugManager"
    :scene-manager="sceneManager"
    :camera-sensitivity="cameraSensitivity"
    :initial-config="initialConfig"
    @config-change="$emit('config-change', $event)"
    @log-debug-info="$emit('log-debug-info')"
    @log-rebase-info="$emit('log-rebase-info')"
    @reset-physics="$emit('reset-physics')"
  >
    <template #extra-sections>
      <!-- 高斯泼溅替换模块列表 -->
      <div v-if="regionModules.length > 0" class="debug-section">
        <h4>🧩 高斯泼溅替换模块</h4>
        <div class="module-select-wrapper">
          <div ref="dropdownRef" class="module-dropdown">
            <div class="module-dropdown-trigger" @click="toggleDropdown">
              <span class="module-dropdown-text">
                <span class="placeholder-text">选择模块加载/卸载</span>
              </span>
              <span class="dropdown-arrow" :class="{ 'arrow-up': dropdownOpen }">▼</span>
            </div>
            <div v-if="dropdownOpen" class="module-dropdown-menu">
              <div class="module-search-box">
                <input
                  ref="searchInputRef"
                  v-model="searchKeyword"
                  type="text"
                  class="module-search-input"
                  placeholder="🔍 搜索模块..."
                  @click.stop
                />
              </div>
              <div class="module-dropdown-list">
                <div
                  v-for="module in filteredModules"
                  :key="module.id"
                  class="module-dropdown-item"
                  :class="{
                    'item-loaded': loadedModules.has(module.name),
                    'item-loading': loadingModules.has(module.name),
                  }"
                  @click="onSelectModule(module)"
                >
                  <span class="module-item-status">
                    <span v-if="loadingModules.has(module.name)" class="loading-spinner">⏳</span>
                    <span v-else-if="loadedModules.has(module.name)">✅</span>
                    <span v-else>⬜</span>
                  </span>
                  <span class="module-item-name">{{ module.name }}</span>
                  <span class="module-item-action">
                    <span v-if="loadingModules.has(module.name)">加载中...</span>
                    <span v-else-if="loadedModules.has(module.name)" class="action-unload">点击卸载</span>
                    <span v-else class="action-load">点击加载</span>
                  </span>
                </div>
                <div v-if="filteredModules.length === 0" class="module-dropdown-empty">
                  无匹配模块
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </template>
  </DebugPanel>
</template>

<script setup lang="ts">
import { ref, reactive, computed, nextTick } from 'vue';
import DebugPanel from './DebugPanel.vue';
import type { DebugConfig } from '@tencent/viewer-sdk';

interface RegionModuleInfo {
  id: string;
  name: string;
}

interface Props {
  debugManager?: any;
  sceneManager?: any;
  cameraSensitivity?: number;
  initialConfig?: Partial<DebugConfig>;
}

withDefaults(defineProps<Props>(), {
  cameraSensitivity: 0.003,
});

const emit = defineEmits<{
  'config-change': [config: DebugConfig];
  'gaussian-bounds-y-offset-change': [yOffset: number];
  'log-debug-info': [];
  'log-rebase-info': [];
  'reset-physics': [];
  'module-toggle': [moduleName: string, shouldLoad: boolean];
}>();

// 区域替换模块列表
const regionModules = ref<RegionModuleInfo[]>([]);
// 已加载的模块集合
const loadedModules = reactive(new Set<string>());
// 正在加载中的模块集合
const loadingModules = reactive(new Set<string>());

// 持有 DebugPanel 实例，用于外部命令式同步 checkbox 状态（如浮层切换碰撞体可视化）
const debugPanelRef = ref<InstanceType<typeof DebugPanel> | null>(null);

// 下拉菜单是否展开
const dropdownOpen = ref(false);
// 搜索关键词
const searchKeyword = ref('');
// DOM 引用
const dropdownRef = ref<HTMLElement | null>(null);
const searchInputRef = ref<HTMLInputElement | null>(null);

// 根据搜索关键词过滤的模块列表
const filteredModules = computed(() => {
  const keyword = searchKeyword.value.trim().toLowerCase();
  if (!keyword) return regionModules.value;
  return regionModules.value.filter((m) =>
    m.name.toLowerCase().includes(keyword)
  );
});

/**
 * 切换下拉菜单展开/收起
 */
function toggleDropdown() {
  dropdownOpen.value = !dropdownOpen.value;
  if (dropdownOpen.value) {
    searchKeyword.value = '';
    nextTick(() => {
      searchInputRef.value?.focus();
    });
  }
}

/**
 * 选中某个模块，直接执行加载/卸载
 */
function onSelectModule(module: RegionModuleInfo) {
  const moduleName = module.name;
  if (loadingModules.has(moduleName)) return; // 加载中，忽略点击

  const isLoaded = loadedModules.has(moduleName);

  if (isLoaded) {
    // 卸载
    loadedModules.delete(moduleName);
    emit('module-toggle', moduleName, false);
  } else {
    // 加载
    loadingModules.add(moduleName);
    emit('module-toggle', moduleName, true);
  }
}

/**
 * 标记模块加载完成（供父组件调用）
 */
function onModuleLoaded(moduleName: string) {
  loadingModules.delete(moduleName);
  loadedModules.add(moduleName);
}

/**
 * 标记模块加载失败（供父组件调用）
 */
function onModuleLoadFailed(moduleName: string) {
  loadingModules.delete(moduleName);
}

/**
 * 标记模块已卸载（供父组件调用）
 */
function onModuleUnloaded(moduleName: string) {
  loadedModules.delete(moduleName);
  loadingModules.delete(moduleName);
}

/**
 * 设置区域替换模块列表（供父组件在场景就绪后调用）
 */
function setRegionModules(modules: Array<{ id?: string; name: string }>) {
  regionModules.value = modules.map((m) => ({
    id: m.id || m.name,
    name: m.name,
  }));
}

/**
 * 获取当前正在加载中的模块名列表（供父组件调用）
 */
function getLoadingModules(): string[] {
  return [...loadingModules];
}

/**
 * 命令式：把部分调试配置同步到内嵌的 DebugPanel checkbox。
 * 仅同步 UI 状态，不会 emit 回 config-change（由调用方决定是否再调 viewerSDK）。
 */
function applyDebugConfig(partial: Partial<DebugConfig>) {
  debugPanelRef.value?.applyConfig?.(partial);
}

// 暴露方法给父组件
defineExpose({
  onModuleLoaded,
  onModuleLoadFailed,
  onModuleUnloaded,
  setRegionModules,
  getLoadingModules,
  applyDebugConfig,
});


</script>

